use crate::position::AccountBalance;

/// The most recent balance for one account, or none.
///
/// LATEST, because `position` rolls forward from it: the nearer the observation, the fewer
/// transactions have to be applied on top and the less there is to get wrong.
pub fn latest_for<'a>(balances: &'a [AccountBalance], account: &str) -> Option<&'a AccountBalance> {
    balances.iter().filter(|b| b.account == account).max_by(|a, b| a.as_of.cmp(&b.as_of))
}
